function basename(path) {
  const parts = String(path).split(/[\\/]/);
  return parts[parts.length - 1] || 'test19.mjs';
}

function usage(program) {
  return `usage: ${program} [-h] --a A`;
}

function help(program) {
  return `${usage(program)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Nested dictionary structure\n`;
}

function looksLikeOption(token) {
  return token.startsWith('-') && token !== '-';
}

export function parseArgs(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const program = basename(scriptPath ?? 'test19.mjs');
  let aValue;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', program };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || looksLikeOption(nextToken)) {
        return {
          kind: 'error',
          program,
          message: 'argument --a: expected one argument',
        };
      }
      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      program,
      message: 'the following arguments are required: --a',
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      program,
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'ok',
    program,
    a: aValue,
  };
}

export function writeHelp(program) {
  process.stdout.write(help(program));
}

export function writeError(program, message) {
  process.stderr.write(`${usage(program)}\n${program}: error: ${message}\n`);
